DROP TABLE IF EXISTS `programas_en`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `programas_en` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_disciplina` tinyint(2) NOT NULL,
  `id_grupo` int(11) NOT NULL,
  `programa` varchar(255) NOT NULL,
  `imagen` varchar(255) DEFAULT NULL,
  `texto` text NOT NULL,
  `publicado` tinyint(1) NOT NULL DEFAULT 1,
  `alta` timestamp NOT NULL DEFAULT current_timestamp(),
  `actualiza` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_id` (`id`),
  UNIQUE KEY `uq_programa` (`programa`),
  UNIQUE KEY `uq_imagen` (`imagen`),
  KEY `fk_programen_dis` (`id_disciplina`),
  KEY `fk_programen_intro` (`id_grupo`),
  CONSTRAINT `fk_programen_dis` FOREIGN KEY (`id_disciplina`) REFERENCES `disciplinas` (`id`),
  CONSTRAINT `fk_programen_intro` FOREIGN KEY (`id_grupo`) REFERENCES `grupo_en` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
