CREATE TABLE `programas_es` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_disciplina` tinyint(2) NOT NULL,
  `id_grupo` int(11) NOT NULL,
  `programa` varchar(255) NOT NULL,
  `imagen` varchar(255) DEFAULT NULL,
  `texto` text NOT NULL,
  `publicado` tinyint(1) NOT NULL DEFAULT 1,
  `alta` timestamp NOT NULL DEFAULT current_timestamp(),
  `actualiza` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_id` (`id`),
  UNIQUE KEY `uq_programa` (`programa`),
  UNIQUE KEY `uq_imagen` (`imagen`),
  KEY `fk_programes_dis` (`id_disciplina`),
  KEY `fk_programes_intro` (`id_grupo`),
  CONSTRAINT `fk_programes_dis` FOREIGN KEY (`id_disciplina`) REFERENCES `disciplinas` (`id`),
  CONSTRAINT `fk_programes_intro` FOREIGN KEY (`id_grupo`) REFERENCES `grupo_es` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

